const KEY='sarah-studio-v1';
const PROJECT_STATUSES=['Planned','In Progress','On Hold','Completed','Abandoned'];
const CRAFT_TYPES=['Knitting','Crochet'];
const starter={active:'p1',projects:[{id:'p1',name:'Cozy Cardigan',status:'In Progress',craftType:'Knitting',activeSection:'s1',activeVersion:'v1',sections:[{id:'s1',name:'Ribbed Border',rows:40,count:24,weight:40,done:false},{id:'s2',name:'Body',rows:100,count:0,weight:40,done:false},{id:'s3',name:'Finishing',rows:10,count:0,weight:20,done:false,isFinishing:true}],versions:[{id:'v1',name:'Original instructions',content:'K2, P2 repeat across the row.\nContinue ribbed border for 40 rows.',original:true}],notes:[],videos:[{title:'How to Knit a Ribbed Border (K2, P2)',url:'https://www.youtube.com/results?search_query=how+to+knit+ribbed+border'}],history:[],archived:false}],yarn:[],tools:[],gifts:[],ideas:[],deleted:[],updated:new Date().toISOString()};
let state=structuredClone(starter),page='Home',modal=null,query='';
let dropboxFeedback='';
let patternDeleteSelection=new Set(),patternDeleteScope='';
let layoutEdit=false,dragWidget=null;
// Embedded PDF reader is retained across dashboard redraws, including row-counter updates.
let inlinePdfReader=null,inlinePdfProject=null,inlinePdfStarting=false;
let giftMonth=new Date().getMonth(),giftYear=new Date().getFullYear(),selectedGiftDay=null;
const WIDGET_DEFAULT=['project-selector','video-card','pattern-card','counter-card'];
const layoutKey='sarah-studio-dashboard-order-v3.7';
const bannerKey='sarah-studio-banner-photo-v3.2';
const bannerPosKey='sarah-studio-banner-position-v3.2';
function widgetOrder(){try{const x=JSON.parse(localStorage.getItem(layoutKey));return Array.isArray(x)&&x.length===4&&WIDGET_DEFAULT.every(y=>x.includes(y))?x:WIDGET_DEFAULT.slice()}catch{return WIDGET_DEFAULT.slice()}}
function bannerPhoto(){return localStorage.getItem(bannerKey)||''}
function bannerPos(){return Number(localStorage.getItem(bannerPosKey)||50)}
function hero(){return `<div class="hero" style="--photo-position:${bannerPos()}%"><div class="hero-photo" ${bannerPhoto()?`style="background-image:url('${bannerPhoto()}')"`:''}></div><div class="hero-copy"><h1>Make. Plan. Gift. Repeat.</h1><p>Your crochet and knitting workspace</p></div><div class="hero-controls"><label class="button secondary small photo-label">Change photo<input id="bannerUpload" type="file" accept="image/*" hidden></label><button class="button secondary small" data-action="repositionBanner">Reposition</button><button class="button secondary small" data-action="resetBanner">Restore original</button></div></div>`}
function arrangeWidgets(html){const wrapper=document.createElement('div');wrapper.innerHTML=html;const dash=wrapper.querySelector('.dashboard');if(!dash)return html;const cards=[...dash.children];const map=new Map(cards.map(x=>[WIDGET_DEFAULT.find(c=>x.classList.contains(c)),x]));dash.replaceChildren(...widgetOrder().map(k=>map.get(k)));dash.classList.toggle('layout-edit',layoutEdit);for(const card of dash.children){const key=WIDGET_DEFAULT.find(c=>card.classList.contains(c));card.dataset.widget=key;if(layoutEdit){card.draggable=true;card.insertAdjacentHTML('afterbegin',`<div class="widget-grip"><span>↕ Drag to reorder</span><div><button class="button secondary small" data-move="-1" aria-label="Move widget earlier">↑</button><button class="button secondary small" data-move="1" aria-label="Move widget later">↓</button></div></div>`)}}return dash.outerHTML}
function dashboardControls(){return `<div class="layout-controls"><button class="button secondary small" data-action="toggleLayout">${layoutEdit?'Done editing':'Edit layout'}</button>${layoutEdit?'<button class="button secondary small" data-action="resetLayout">Reset layout</button>':''}</div>`}

let persistenceReady=false, pendingWrites=Promise.resolve();
function persist(){if(!persistenceReady)return;const snapshot=structuredClone(state);pendingWrites=pendingWrites.then(()=>StudioDB.put(snapshot)).catch(e=>{console.error('Save failed',e);alert('Local save failed. Export a backup before closing this page.');});}
function versionSnapshot(p){if(!p)return; p.versionSectionStates??={};p.versionSectionStates[p.activeVersion]=Object.fromEntries(p.sections.map(x=>[x.id,{count:x.count,done:x.done}]));}
function switchVersion(p,next){versionSnapshot(p);p.activeVersion=next;p.versionSectionStates??={};const saved=p.versionSectionStates[next]||{};for(const x of p.sections){x.count=saved[x.id]?.count??0;x.done=saved[x.id]?.done??false;}p.versionSectionStates[next]??=Object.fromEntries(p.sections.map(x=>[x.id,{count:x.count,done:x.done}]));}
function normalizedProject(p){if(p.status==='In progress')p.status='In Progress';p.versionSectionStates??={};if(!p.versionSectionStates[p.activeVersion])versionSnapshot(p);return p;}
function prepareState(x){if(!x||!Array.isArray(x.projects))throw Error('Invalid project data');for(const p of x.projects){if(!Array.isArray(p.sections)||!Array.isArray(p.versions))throw Error('Invalid project sections or versions');normalizedProject(p);}return x;}

function load(){try{const x=JSON.parse(localStorage.getItem(KEY));return x&&Array.isArray(x.projects)?x:structuredClone(starter)}catch{return structuredClone(starter)}}
function save(){versionSnapshot(active());state.updated=new Date().toISOString();persist();render()}
const id=()=>crypto.randomUUID?.()||String(Date.now()+Math.random());
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const active=()=>state.projects.find(p=>p.id===state.active&&!p.archived)||state.projects.find(p=>!p.archived);
const sec=p=>p?.sections.find(s=>s.id===p.activeSection)||p?.sections[0];
const ver=p=>p?.versions.find(v=>v.id===p.activeVersion)||p?.versions[0];
const patternRowStats=v=>{const columns=patternColumns(v),done=v?.completedLines||{};let total=0,completed=0;columns.forEach((content,col)=>String(content).split('\n').forEach((line,i)=>{if(!line.trim())return;total++;if(done[col+':'+i])completed++}));return {total,completed,percent:total?Math.round(100*completed/total):0}};
const progressStats=p=>{if(!p)return {overall:0,section:0,completed:0,total:0};const sections=p.sections.filter(s=>!s.isFinishing);const total=sections.reduce((n,s)=>n+Math.max(0,safeNumber(s.rows)),0);const completed=sections.reduce((n,s)=>n+Math.min(Math.max(0,safeNumber(s.count)),Math.max(0,safeNumber(s.rows))),0);const tasks=Array.isArray(p.finishingTasks)?p.finishingTasks:[];const weight=tasks.length?Math.max(0,Math.min(100,safeNumber(p.finishingWeight??10))):0;const overall=total?Math.round((100-weight)*completed/total+weight*(tasks.length?tasks.filter(t=>t.done).length/tasks.length:0)):tasks.length?Math.round(100*tasks.filter(t=>t.done).length/tasks.length):0;const s=sec(p);return {overall:Math.min(100,overall),section:s?.rows?Math.round(100*Math.min(Math.max(0,safeNumber(s.count)),safeNumber(s.rows))/safeNumber(s.rows)):0,completed,total}};
const percent=p=>progressStats(p).overall;
const safeNumber=v=>Number.isFinite(+v)?+v:0;
function logo(){return `<div class="brand"><img src="approved-logo.png" alt="Terracotta yarn ball and crossed olive-green knitting needles"><span>Sarah's<br>Stitched Gifts Studio</span></div>`}
const nav=['Home','Projects','Patterns','Yarn Inventory','Tools','Ideas & Requests','Gift Planner','Stitch Counters','Completed','Backup & Sync','Settings'];
function navHtml(){return nav.map(n=>`<button class="${page===n?'active':''}" data-nav="${esc(n)}">${esc(n)}</button>`).join('')}
let mobileMoreOpen=false;
function render(){const p=active();
 const carry=inlinePdfReader&&page==='Home'&&p?.id===inlinePdfProject?inlinePdfReader.root:null;
 if(carry)carry.remove();
 else if(inlinePdfReader){const previous=inlinePdfReader;inlinePdfReader=null;inlinePdfProject=null;previous.close();}
 document.querySelector('#app').innerHTML=`<div class="shell"><aside class="sidebar">${logo()}<div class="nav">${navHtml()}</div></aside><main class="main"><header class="top">${innerWidth<=650?logo():`<input class="search" placeholder="Search patterns, yarn, projects..." value="${esc(query)}" id="search">`}<button class="button" data-action="newProject">+ New project</button></header>${page==='Home'?home(p):other()}<footer class="muted" style="margin-top:25px">Local-only preview • Data is saved in this browser • Dropbox sync available in Backup & Sync (manual, experimental)</footer></main></div><nav class="bottom-nav" aria-label="Mobile navigation">${['Home','Projects','Yarn Inventory'].map(n=>`<button data-nav="${n}" class="${page===n?'active':''}">${n==='Yarn Inventory'?'Yarn':n}</button>`).join('')}<button data-action="mobileMore" class="${!['Home','Projects','Yarn Inventory'].includes(page)?'active':''}" aria-label="More sections" aria-expanded="${mobileMoreOpen}">More</button></nav>${mobileMoreOpen?`<div class="mobile-more-backdrop" data-action="closeMobileMore"></div><section class="mobile-more-panel" aria-label="More app sections"><div class="row spread"><strong>More</strong><button class="button secondary small" data-action="closeMobileMore">Close</button></div><div class="mobile-more-links">${nav.filter(n=>!['Home','Projects','Yarn Inventory'].includes(n)).map(n=>`<button data-nav="${esc(n)}" class="${page===n?'active':''}">${esc(n)}</button>`).join('')}</div></section>`:''}${modal||''}`;bind();bindCustom();if(carry){const mount=document.querySelector('#homePdfReaderMount');if(mount){mount.append(carry);inlinePdfReader?.refreshCounter?.();}else{inlinePdfReader=null;inlinePdfProject=null;}}}
function patternColumns(v){return Array.isArray(v?.columns)&&v.columns.length?v.columns:[String(v?.content||'')]}
function patternDisplay(p,s,v){const scope=(p?.id||'')+':'+(v?.id||'');if(scope!==patternDeleteScope){patternDeleteSelection.clear();patternDeleteScope=scope}const columns=patternColumns(v),done=v?.completedLines||{},current=v?.currentLine||'',stats=patternRowStats(v);return '<div class="pattern-row-summary" role="status"><strong>'+stats.completed+' / '+stats.total+' rows completed · '+stats.percent+'%</strong><div class="progress-track"><div class="progress-fill" style="width:'+stats.percent+'%"></div></div><span class="muted">Counts non-empty lines in this working pattern. Delete imported headings or other non-stitch lines to exclude them.</span></div>'+(!v?.original?'<div class="pattern-bulk-actions"><button type="button" class="button secondary small" data-pattern-bulk-delete '+(patternDeleteSelection.size?'':'disabled')+'>Delete selected lines ('+patternDeleteSelection.size+')</button><button type="button" class="button secondary small" data-pattern-clear-selection '+(patternDeleteSelection.size?'':'disabled')+'>Clear selection</button></div>':'')+'<div class="pattern-columns cols-'+columns.length+'">'+columns.map((content,col)=>'<section class="pattern-column"><div class="pattern-column-header">Column '+(col+1)+'</div>'+String(content).split('\n').map((line,i)=>{if(!line.trim())return '';const key=col+':'+i,isCurrent=current===key;return '<div class="pattern-line'+(isCurrent?' current-pattern-row':'')+'"><input type="checkbox" data-pattern-check="'+esc(key)+'" '+(done[key]?'checked':'')+' aria-label="Complete column '+(col+1)+' line '+(i+1)+'"><button type="button" class="pattern-focus" data-pattern-focus="'+esc(key)+'" aria-label="Highlight column '+(col+1)+' line '+(i+1)+'">'+(isCurrent?'●':'○')+'</button><span class="pattern-text">'+esc(line)+'</span>'+(!v?.original?'<label class="pattern-select-label"><input type="checkbox" data-pattern-select="'+esc(key)+'" '+(patternDeleteSelection.has(key)?'checked':'')+' aria-label="Select column '+(col+1)+' line '+(i+1)+' for deletion"><span>Select</span></label>':'')+'</div>'}).join('')+'</section>').join('')+'</div>'}
function deleteWorkingPatternLine(v,key){if(!v||v.original)return false;const parts=/^(\d+):(\d+)$/.exec(key);if(!parts)return false;const col=Number(parts[1]),index=Number(parts[2]),columns=patternColumns(v).slice();if(col>=columns.length)return false;const lines=String(columns[col]).split('\n');if(index>=lines.length)return false;lines.splice(index,1);columns[col]=lines.join('\n');const next={};for(const [k,value] of Object.entries(v.completedLines||{})){const match=/^(\d+):(\d+)$/.exec(k);if(!match)continue;const c=Number(match[1]),i=Number(match[2]);if(c===col&&i===index)continue;next[c+':'+(c===col&&i>index?i-1:i)]=value}v.completedLines=next;const current=/^(\d+):(\d+)$/.exec(v.currentLine||'');if(current&&Number(current[1])===col){const i=Number(current[2]);v.currentLine=i===index?'':col+':'+(i>index?i-1:i)}v.columns=columns;v.content=columns.join('\n\n');return true}
function deleteWorkingPatternLines(v,keys){if(!v||v.original||!keys?.size)return 0;const columns=patternColumns(v).slice(),removed=new Map(),indexMaps=new Map();let removedCount=0;for(const [col,content] of columns.entries()){const original=String(content).split('\n'),kept=[],indexes=new Map();original.forEach((line,i)=>{if(keys.has(col+':'+i)){removedCount++;return}indexes.set(i,kept.length);kept.push(line)});removed.set(col,new Set(original.map((_,i)=>i).filter(i=>keys.has(col+':'+i))));indexMaps.set(col,indexes);columns[col]=kept.join('\n')}if(!removedCount)return 0;const next={};for(const [key,value] of Object.entries(v.completedLines||{})){const match=/^(\d+):(\d+)$/.exec(key);if(!match)continue;const col=Number(match[1]),i=Number(match[2]),mapped=indexMaps.get(col)?.get(i);if(mapped!==undefined)next[col+':'+mapped]=value}const current=/^(\d+):(\d+)$/.exec(v.currentLine||'');if(current){const col=Number(current[1]),i=Number(current[2]),mapped=indexMaps.get(col)?.get(i);v.currentLine=mapped===undefined?'':col+':'+mapped}v.columns=columns;v.content=columns.join('\n\n');v.completedLines=next;return removedCount}
function pdfLink(p){const url=p?.dropboxPdfUrl;return '<div class="project-pdf"><span class="muted">Original Pattern PDF (Dropbox)</span><div class="row pdf-actions">'+(url?'<a class="button secondary small" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">View PDF</a>':'<span class="muted">No PDF linked</span>')+'<button class="button secondary small" data-action="setDropboxLink">'+(url?'Change link':'Add Dropbox link')+'</button>'+(url?'<button class="button small" data-action="openPdfReader">Open Pattern Reader</button>':'')+'</div></div>'}
function home(p){if(!p)return `${hero()}<div class="card">Create a project to begin.</div>`;const s=sec(p),v=ver(p);return `${hero()}${dashboardControls()}${arrangeWidgets(`<div class="dashboard"><section class="card project-selector"><div class="row spread project-heading"><div><h2>Current Project</h2><strong class="project-name">${esc(p.name)}</strong><span class="muted"> ${esc(p.status)}</span></div><div><label class="label" for="activeProject">Switch project</label><select id="activeProject" class="field compact-project-select">${state.projects.filter(x=>!x.archived).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div><div class="row project-progress"><span class="muted">${percent(p)}% complete · ${progressStats(p).completed}/${progressStats(p).total} rows</span><div class="progress-track"><div class="progress-fill" style="width:${percent(p)}%"></div></div></div>${pdfLink(p)}</section><section class="card pattern-card"><div class="row spread"><h2>Pattern</h2><button class="button secondary small" data-nav="Patterns">Open full pattern</button></div><div class="inline-grid"><div><label class="label">Active section</label>${s?`<select class="field" id="activeSection">${p.sections.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:`<button class="button secondary small" data-action="newSection">+ Add first section</button>`}</div><div><button class="button secondary small" data-action="newSection">+ Add section</button></div><div><label class="label">Pattern version</label><select class="field" id="activeVersion">${p.versions.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div><div class="row pdf-inline-actions">${p.dropboxPdfUrl?'<button class="button secondary small" data-action="openInlinePdf">Show PDF in this widget</button>':'<span class="muted">Link a Dropbox PDF above to read it here.</span>'}</div><div id="homePdfReaderMount" class="home-pdf-reader-mount"></div><div class="instructions">${patternDisplay(p,s,v)}</div><div class="row spread"><span class="muted">${p.notes.length} personal note(s)</span><button class="button secondary small" data-action="importInstructions">Import PDF text</button><button class="button secondary small" data-action="organizeColumns">Arrange columns</button><button class="button secondary small" data-action="addNote">+ Add note</button></div></section><section class="card counter-card"><h2>Row Counter</h2>${s?`<div class="muted">${esc(s.name)} · ${progressStats(p).section}% of section</div><div class="counter-buttons"><button class="round" data-action="minus" aria-label="Decrease row count">−</button><div style="text-align:center"><div class="counter-number">${s.count}</div><div class="muted">of ${s.rows} rows</div></div><button class="round plus" data-action="plus" aria-label="Increase row count">+</button></div><div class="row spread"><span class="muted" role="status">Section: ${s.rows>0&&s.count>=s.rows?'Complete':'In progress'}</span><button class="button secondary small" data-action="editSection">Edit section</button></div><div class="muted">Overall: ${percent(p)}%</div><button class="button secondary small" data-action="finishingSetup">Finishing settings</button>${(p.finishingTasks||[]).map(t=>`<label class="row"><input type="checkbox" data-finishing-task="${t.id}" ${t.done?'checked':''}> ${esc(t.name)}</label>`).join('')}`:`<div class="counter-buttons"><div style="text-align:center"><div class="counter-number">0</div><div class="muted">Add a section to start counting</div></div></div><button class="button secondary small" data-action="newSection">+ Add first section</button>`}</section><section class="card video-card"><h2>YouTube Tutorials</h2>${(p.videos||[]).length?(()=>{const video=p.videos[0],id=StudioTutorials.videoId(video.url);return `<div class="video-preview"><div class="inline-video-content"><strong>${esc(video.title)}</strong>${id?`<div class="studio-inline-player"><iframe title="${esc(video.title)}" src="https://www.youtube-nocookie.com/embed/${id}?playsinline=1&amp;rel=0" allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div><p class="muted studio-inline-help">Use the video controls here while viewing your pattern and row counter.</p>`:`<p class="muted">This saved link points to YouTube search results, not an individual video. Use Find tutorials to choose a video to play here.</p>`}<a class="video-external-link" href="${esc(video.url)}" target="_blank" rel="noopener noreferrer" aria-label="Open this tutorial on YouTube (external website)">YouTube ↗</a></div></div>`})():'<p class="empty">No tutorial selected. Use Find tutorials to choose one.</p>'}<div class="row" style="margin-top:12px;flex-wrap:wrap"><button class="button secondary small" data-action="addVideo">+ Save video link</button><button class="button" data-action="youtubeSearch">Find tutorials</button></div></section></div>`)}`}

function reorderWidget(key,delta){const order=widgetOrder(),i=order.indexOf(key),j=i+delta;if(i<0||j<0||j>=order.length)return;order.splice(i,1);order.splice(j,0,key);localStorage.setItem(layoutKey,JSON.stringify(order));render()}
function bindCustom(){
 document.querySelector('#bannerUpload')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return alert('Choose an image file.');if(file.size>8*1024*1024)return alert('Choose a photo smaller than 8 MB.');try{const img=await createImageBitmap(file);const c=document.createElement('canvas'),scale=Math.min(1,1600/img.width,1000/img.height);c.width=Math.round(img.width*scale);c.height=Math.round(img.height*scale);c.getContext('2d').drawImage(img,0,0,c.width,c.height);localStorage.setItem(bannerKey,c.toDataURL('image/jpeg',.8));render()}catch(err){alert('Photo could not be saved. Try a smaller image.')}});
 document.querySelectorAll('[data-move]').forEach(b=>b.addEventListener('click',e=>{e.preventDefault();reorderWidget(b.closest('[data-widget]').dataset.widget,Number(b.dataset.move))}));
 const dash=document.querySelector('.dashboard');if(!dash||!layoutEdit)return;
 dash.querySelectorAll('[data-widget]').forEach(card=>{
  card.addEventListener('dragstart',e=>{dragWidget=card.dataset.widget;e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',dragWidget);card.classList.add('dragging')});
  card.addEventListener('dragend',()=>{dragWidget=null;card.classList.remove('dragging')});
  card.addEventListener('dragover',e=>{e.preventDefault();e.dataTransfer.dropEffect='move';card.classList.add('drop-target')});
  card.addEventListener('dragleave',()=>card.classList.remove('drop-target'));
  card.addEventListener('drop',e=>{e.preventDefault();card.classList.remove('drop-target');const from=dragWidget||e.dataTransfer.getData('text/plain'),to=card.dataset.widget;if(!from||from===to)return;const order=widgetOrder();order.splice(order.indexOf(from),1);order.splice(order.indexOf(to),0,from);localStorage.setItem(layoutKey,JSON.stringify(order));render()});
 });
}


function giftCalendar(){
 const first=new Date(giftYear,giftMonth,1).getDay(),days=new Date(giftYear,giftMonth+1,0).getDate();
 const monthName=new Intl.DateTimeFormat('en-US',{month:'long',year:'numeric'}).format(new Date(giftYear,giftMonth,1));
 const cells=[];
 for(let i=0;i<first;i++)cells.push('<div class="gift-day blank" aria-hidden="true"></div>');
 for(let day=1;day<=days;day++){
  const date=`${giftYear}-${String(giftMonth+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`;
  const matches=state.gifts.filter(g=>g.date===date);
  cells.push(`<button type="button" class="gift-day ${matches.length?'has-gifts':''} ${selectedGiftDay===date?'selected':''}" data-gift-day="${date}" aria-label="${date}: ${matches.length} gift deadlines"><span>${day}</span>${matches.length?`<small>${matches.length} ${matches.length===1?'gift':'gifts'}</small>`:''}</button>`);
 }
 const chosen=selectedGiftDay?state.gifts.filter(g=>g.date===selectedGiftDay):[];
 return `<section class="card gift-calendar"><div class="row spread gift-calendar-heading"><h2>Gift Deadline Calendar</h2><div class="row"><button class="button secondary small" data-gift-month="-1" aria-label="Previous month">‹</button><strong>${monthName}</strong><button class="button secondary small" data-gift-month="1" aria-label="Next month">›</button></div></div><p class="muted">Only gifts with deadlines appear here. Gifts without dates remain in the list below.</p><div class="gift-calendar-grid">${['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<span class="gift-weekday">${x}</span>`).join('')}${cells.join('')}</div>${selectedGiftDay?`<div class="gift-day-detail"><strong>${selectedGiftDay}</strong>${chosen.length?chosen.map(g=>`<p>${esc(g.recipient)}${g.project?' • '+esc(g.project):''}</p>`).join(''):'<p>No gift deadlines on this date.</p>'}</div>`:''}</section>`;
}
function giftFields(g={}){return [{name:'recipient',label:'Recipient',value:g.recipient||'',required:true},{name:'project',label:'Project (optional)',value:g.project||''},{name:'date',label:'Gift deadline (optional)',type:'date',value:g.date||''},{name:'reminder',label:'Reminder date (optional)',type:'date',value:g.reminder||''}];}

function other(){const p=active(),q=query.toLowerCase();let body='';const projectPicker=()=>p?`<div class="card"><label class="label" for="activeProject">Current project</label><select id="activeProject" class="field">${state.projects.filter(x=>!x.archived).map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><span class="muted">Patterns and stitch counters belong to the selected project.</span></div>`:'';const head=(t,action,label)=>`<div class="section-header"><h1>${t}</h1>${action?`<button class="button" data-action="${action}">${label||'+ Add'}</button>`:''}</div>`;
if(page==='Projects'||page==='Completed'){const ps=state.projects.filter(x=>page==='Completed'?x.archived:x.status!=='Completed'&&!x.archived).filter(x=>x.name.toLowerCase().includes(q));body=head(page,'newProject','+ Project')+`<div class="list">${ps.map(x=>`<div class="list-item"><strong>${esc(x.name)}</strong><span class="muted">${esc(x.status)} • ${percent(x)}% complete • ${x.sections.length} sections</span><div class="actions"><button class="button small" data-choose="${x.id}">Open</button><button class="button secondary small" data-duplicate="${x.id}">Duplicate</button><button class="button secondary small" data-archive="${x.id}">${x.archived?'Restore':'Archive'}</button></div></div>`).join('')||'<div class="empty">No projects here yet.</div>'}</div>`}
else if(page==='Patterns'){body=head('Patterns & Modifications','addNote','+ Note')+projectPicker()+(p?`<div class="card stack"><div class="row spread"><label class="label">Project: ${esc(p.name)}</label><button class="button secondary small" data-action="newSection">+ Add section</button></div><label class="label">Active section</label>${p.sections.length?`<select class="field" id="activeSection">${p.sections.map(x=>`<option value="${x.id}" ${x.id===sec(p)?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'<span class="muted">No sections yet. Add a section to begin.</span>'}<label class="label">Pattern version</label><select class="field" id="activeVersion">${p.versions.map(v=>`<option value="${v.id}" ${v.id===p.activeVersion?'selected':''}>${esc(v.name)}${v.original?' (original)':''}</option>`).join('')}</select><div class="instructions">${patternDisplay(p,sec(p),ver(p))}</div>${pdfLink(p)}<div class="row" style="flex-wrap:wrap"><button class="button secondary small" data-action="newVersion">Create modified working copy</button><button class="button secondary small" data-action="editVersion" ${ver(p).original?'disabled title="Original is read-only"':''}>Edit working copy</button><button class="button secondary small" data-action="importInstructions">Import instructions from PDF</button><button class="button secondary small" data-action="organizeColumns">Arrange columns</button><button class="button secondary small" data-action="importPattern">Attach PDF / image (5 MB)</button></div><h2>Notes</h2>${p.notes.map(n=>`<div class="note"><strong>${esc(n.section||'General')}</strong><p>${esc(n.text)}</p><button class="button secondary small" data-delete-note="${n.id}">Delete note</button></div>`).join('')||'<div class="muted">No notes yet.</div>'}${p.attachment?`<div><a href="${esc(p.attachment.data)}" download="${esc(p.attachment.name)}">Download attached pattern: ${esc(p.attachment.name)}</a></div>`:''}</div>`:'<p>Create a project first.</p>')}
else if(page==='Stitch Counters'){body=head('Stitch Counters','newSection','+ Section')+projectPicker()+(p?`<div class="card stack"><label class="label" for="activeSection">Active section</label>${p.sections.length?`<select id="activeSection" class="field">${p.sections.map(x=>`<option value="${x.id}" ${x.id===sec(p)?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select>`:'<span class="muted">No sections yet. Add a section to start counting.</span>'}<span class="muted">${progressStats(p).completed}/${progressStats(p).total} rows completed · ${percent(p)}% overall</span></div><div class="list">${p.sections.map(s=>`<div class="list-item"><strong>${esc(s.name)}</strong><div class="row spread"><span>${s.count} / ${s.rows} rows • ${s.rows>0?Math.round(100*Math.min(Math.max(0,s.count),s.rows)/s.rows):0}% complete</span><span class="tag">${s.rows>0&&s.count>=s.rows?'Complete':'In progress'}</span></div><div class="actions"><button class="button small" data-counter="${s.id}" data-delta="-1">−</button><button class="button small" data-counter="${s.id}" data-delta="1">+</button><button class="button secondary small" data-editsection="${s.id}">Edit</button></div></div>`).join('')}</div>`:'<p>Create a project first.</p>')}
else if(page==='Yarn Inventory'){body=head('Yarn Inventory','newYarn','+ Yarn')+`<div class="list">${state.yarn.filter(y=>y.name.toLowerCase().includes(q)).map(y=>`<div class="list-item"><strong>${esc(y.name)}</strong><span class="muted">${esc(y.weight||'Unspecified weight')}</span><p>Total ${y.total} • Reserved ${y.reserved} • Used ${y.used} • Available ${Math.max(0,y.total-y.reserved-y.used)} ${esc(y.unit||'skeins')}</p><button class="button secondary small" data-yarn="${y.id}">Adjust quantities</button></div>`).join('')||'<div class="empty">No yarn recorded.</div>'}</div>`}
else if(page==='Tools'){body=head('Tools','newTool','+ Tool')+`<div class="list">${state.tools.map(x=>`<div class="list-item"><strong>${esc(x.name)}</strong><span class="muted">${esc(x.size||'')}</span></div>`).join('')||'<div class="empty">No tools recorded.</div>'}</div>`}
else if(page==='Gift Planner'){body=head('Gift Planner','newGift','+ Gift')+giftCalendar()+`<h2 class="gift-list-heading">All planned gifts</h2><div class="list">${state.gifts.map(g=>`<div class="list-item"><strong>${esc(g.recipient)}</strong><p>${esc(g.project||'No project linked')} • ${g.date?'Due '+esc(g.date):'No deadline'}</p><span class="muted">Reminder: ${esc(g.reminder||'None')}</span><div class="actions"><button class="button secondary small" data-edit-gift="${esc(g.id)}">Edit</button><button class="button secondary small" data-delete-gift="${esc(g.id)}">Remove</button></div></div>`).join('')||'<div class="empty">No gifts planned.</div>'}</div>`}
else if(page==='Ideas & Requests'){body=head('Ideas & Requests','newIdea','+ Idea')+`<div class="list">${state.ideas.map(x=>`<div class="list-item"><strong>${esc(x.title)}</strong><p>${esc(x.notes)}</p></div>`).join('')||'<div class="empty">No ideas yet.</div>'}</div>`}
else if(page==='Backup & Sync'){body=head('Backup & Sync')+`<div class="card stack"><h2>Dropbox Connection Status</h2><p id="dropboxStatus" role="status" aria-live="polite"><strong>${esc(StudioDropbox.status())}</strong></p>${dropboxFeedback?'<p id="dropboxFeedback" role="status">'+esc(dropboxFeedback)+'</p>':''}<button class="button" data-action="dropboxTest">Test Connection</button><p class="help">A saved authorization is not proof of a working connection. Test Connection checks Dropbox access without changing files. Renewable authorization is stored in this browser; do not use this feature on a shared device.</p></div><div class="card stack"><h2>Local data and backups</h2><p>Data is saved locally in IndexedDB on this device. iPhone/iPad automatic sync and conflict resolution are <strong>not yet connected</strong>. Do not treat this as your sole copy of important work.</p><div class="row" style="flex-wrap:wrap"><button class="button" data-action="export">Export full JSON backup</button><button class="button secondary" data-action="restore">Restore from JSON</button></div><p class="help">Attachments included in export may make the backup large. Restoring requires explicit confirmation and replaces local records.</p><hr><h2>Dropbox (experimental)</h2><p>Dropbox App Folder access only. Save your public App Key and connect Dropbox. If you connected before automatic renewal was enabled, reconnect once to grant renewable access. Your App Folder restriction stays in place.</p>${StudioDropbox.appKey()?`<p class="help">Dropbox public App Key is configured. Your Dropbox authorization remains separate for each device.</p>`:`<p class="help">Dropbox public App Key has not been configured yet.</p>`}<div class="row" style="flex-wrap:wrap"><button class="button secondary" data-action="dropboxConnect">Connect Dropbox</button><button class="button secondary" data-action="dropboxSync">Sync now</button><button class="button secondary" data-action="dropboxDisconnect">Disconnect</button></div><p class="help">Connection: ${esc(StudioDropbox.status())}. Sync is manual in this milestone. Conflicts are whole-database choices, not per-counter resolution. Export a local backup before first sync.</p><input type="file" id="restoreInput" accept="application/json,.json" hidden></div>`}
else{body=head('Settings')+`<div class="card stack"><h2>About this build</h2><p>Sarah's Stitched Gifts Studio, local-first prototype, storage milestone 2.</p><p>iCloud sync, background reminders, and automatic backups are not yet available. Tutorial search requires optional free search service setup. Checksummed manual export and validated restore work.</p><button class="button secondary" data-nav="Backup & Sync">Backup your data</button></div>`}
return body}
function show(title,fields,submit,extra=''){modal=`<div class="modal-backdrop"><div class="modal"><div class="row spread"><h2>${esc(title)}</h2><button class="button secondary small" data-action="close">✕</button></div><form id="dialogForm" class="form-grid">${fields.map(f=>`<label><span class="label">${esc(f.label)}</span>${f.type==='textarea'?`<textarea class="field" name="${f.name}" ${f.required?'required':''}>${esc(f.value||'')}</textarea>`:f.type==='select'?`<select class="field" name="${f.name}" ${f.required?'required':''}>${f.options.map(option=>`<option value="${esc(option)}" ${option===(f.value??'')?'selected':''}>${esc(option)}</option>`).join('')}</select>`:`<input class="field" name="${f.name}" type="${f.type||'text'}" value="${esc(f.value??'')}" ${f.required?'required':''} ${f.min!=null?`min="${f.min}"`:''}>`}</label>`).join('')}${extra}<button class="button" type="submit">Save</button></form></div></div>`;render();document.querySelector('#dialogForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));submit(d);modal=null;save();if(title==='New section'||title==='Edit section'){const notice=document.createElement('div');notice.setAttribute('role','status');notice.textContent='Section saved successfully';notice.style.cssText='position:fixed;bottom:85px;left:50%;transform:translateX(-50%);background:#214d37;color:white;padding:12px 18px;border-radius:10px;z-index:9999;box-shadow:0 4px 18px #0003';document.body.appendChild(notice);setTimeout(()=>notice.remove(),3500)}}}
function ask(message,fn){if(confirm(message)){fn();save()}}
function action(a){if(a==='mobileMore'){mobileMoreOpen=!mobileMoreOpen;render();return}if(a==='closeMobileMore'){mobileMoreOpen=false;render();return}if(a==='toggleLayout'){layoutEdit=!layoutEdit;render();return}if(a==='resetLayout'){localStorage.removeItem(layoutKey);render();return}if(a==='resetBanner'){if(confirm('Restore the approved banner photo?')){localStorage.removeItem(bannerKey);localStorage.removeItem(bannerPosKey);render()}return}if(a==='repositionBanner'){const n=prompt('Photo position from 0 (top) to 100 (bottom):',bannerPos());if(n!==null&&Number.isFinite(Number(n))){localStorage.setItem(bannerPosKey,String(Math.max(0,Math.min(100,Number(n)))));render()}return}const p=active(),s=sec(p);if(a==='close'){modal=null;render()}else if(a==='newProject')show('New project',[{name:'name',label:'Project name',required:true},{name:'craftType',label:'Craft Type',type:'select',options:CRAFT_TYPES,value:'Knitting',required:true},{name:'status',label:'Status',type:'select',options:PROJECT_STATUSES,value:'Planned',required:true}],d=>{if(!PROJECT_STATUSES.includes(d.status)||!CRAFT_TYPES.includes(d.craftType))return;const x={id:id(),name:d.name,status:d.status,craftType:d.craftType,activeSection:'',activeVersion:'',sections:[],versions:[{id:id(),name:'Original instructions',content:'Add pattern instructions here.',original:true}],notes:[],videos:[],history:[],archived:false};x.activeVersion=x.versions[0].id;state.projects.push(x);state.active=x.id});else if(a==='plus'||a==='minus'){if(!s)return action('newSection');const old=s.count;s.count=Math.max(0,Math.min(999999,s.count+(a==='plus'?1:-1)));p.history.push({at:new Date().toISOString(),section:s.id,from:old,to:s.count});versionSnapshot(p);state.updated=new Date().toISOString();persist();render()}else if(a==='finishingSetup'){p.finishingTasks??=[];show('Finishing settings',[{name:'finishingWeight',label:'Finishing percentage',type:'number',min:0,value:p.finishingWeight??10},{name:'tasks',label:'Finishing tasks (one per line; leave blank for knitting-only projects)',type:'textarea',value:p.finishingTasks.map(t=>t.name).join('\n')}],d=>{const w=Number(d.finishingWeight);if(!Number.isFinite(w)||w<0||w>100)throw Error('Percentage must be 0 to 100');const old=p.finishingTasks;p.finishingWeight=w;p.finishingTasks=String(d.tasks||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(name=>({id:old.find(t=>t.name===name)?.id||id(),name,done:old.find(t=>t.name===name)?.done||false}))})}else if(a==='newSection'||a==='editSection'){const old=a==='editSection'?s:null;show(old?'Edit section':'New section',[{name:'name',label:'Section name',value:old?.name||'',required:true},{name:'rows',label:'Target rows',type:'number',min:0,value:old?.rows||0}],d=>{if(!Number.isFinite(+d.rows)||+d.rows<0)throw Error('Target rows must be zero or greater');if(old)Object.assign(old,{name:d.name,rows:+d.rows});else{const x={id:id(),name:d.name,rows:+d.rows,count:0,weight:0,done:false,isFinishing:false};p.sections.push(x);p.activeSection=x.id}/* Section weights retained for compatibility; progress uses row totals. */})}else if(a==='addNote'){show('Add pattern note',[{name:'section',label:'Section',value:s?.name||'General'},{name:'text',label:'Your note or modification',type:'textarea',required:true}],d=>p.notes.push({id:id(),...d,at:new Date().toISOString()}))}else if(a==='newVersion'){show('Create modified working copy',[{name:'name',label:'Version name',value:'My fit adjustments',required:true},{name:'content',label:'Editable instructions',type:'textarea',value:ver(p).content,required:true}],d=>{const v={id:id(),name:d.name,content:d.content,original:false};versionSnapshot(p);p.versions.push(v);switchVersion(p,v.id)})}else if(a==='editVersion'){const v=ver(p);if(v.original)return;show('Edit working copy',[{name:'name',label:'Version name',value:v.name,required:true},{name:'content',label:'Instructions',type:'textarea',value:v.content,required:true}],d=>{v.name=d.name;v.content=d.content;v.columns=[d.content];v.completedLines={};v.currentLine=''})}else if(a==='addVideo')show('Save YouTube tutorial',[{name:'title',label:'Video title',required:true},{name:'url',label:'YouTube link',type:'url',required:true}],d=>{const u=new URL(d.url);if(!['youtube.com','www.youtube.com','youtu.be','m.youtube.com'].includes(u.hostname)){alert('Please enter a YouTube link.');return}p.videos.unshift(d)});else if(a==='youtubeSearch'){StudioTutorials.openSearch({projectName:p?.name||'',onSave:video=>{if(!p)return;p.videos??=[];if(!p.videos.some(x=>x.url===video.url))p.videos.unshift(video);save()},onSelect:video=>{if(!p)return;p.videos??=[];p.videos=p.videos.filter(x=>x.url!==video.url);p.videos.unshift({title:video.title,url:video.url});page='Home';save();requestAnimationFrame(()=>document.querySelector('.video-card')?.scrollIntoView({block:'nearest',behavior:'smooth'}))}});}else if(a==='openInlinePdf'){
 if(!p?.dropboxPdfUrl){alert('Link a Dropbox PDF first.');return;}
 if(inlinePdfReader){document.querySelector('#homePdfReaderMount')?.scrollIntoView({block:'nearest'});return;}
 if(inlinePdfStarting)return;
 const mount=document.querySelector('#homePdfReaderMount');if(!mount)return;
 inlinePdfStarting=true;
 import('./pdf-reader.js').then(m=>{
   if(page!=='Home'||active()?.id!==p.id){inlinePdfStarting=false;return;}
   return m.openPdfReader({
     mount,url:p.dropboxPdfUrl,reading:p.pdfReading||{},
     onMount:instance=>{inlinePdfReader=instance;inlinePdfProject=p.id;inlinePdfStarting=false;},
     onClose:()=>{if(inlinePdfProject===p.id){inlinePdfReader=null;inlinePdfProject=null;}if(page==='Home'&&active()?.id===p.id)render();},
     onChange:reading=>{p.pdfReading=reading;state.updated=new Date().toISOString();persist();},
     onCounter:{
       get:()=>{const current=sec(p);return {section:current?.name||'No active section',count:current?.count||0,rows:current?.rows||0};},
       change:delta=>{const current=sec(p);if(!current)return;const old=current.count;current.count=Math.max(0,Math.min(999999,current.count+delta));p.history??=[];p.history.push({at:new Date().toISOString(),section:current.id,from:old,to:current.count});versionSnapshot(p);state.updated=new Date().toISOString();persist();render();}
     }
   });
 }).catch(err=>{inlinePdfStarting=false;alert('Could not show PDF in Home: '+err.message);});
}else if(a==='openPdfReader'){
 if(!p?.dropboxPdfUrl){alert('Add a Dropbox PDF link to this project first.');return}
 import('./pdf-reader.js').then(m=>m.openPdfReader({
   url:p.dropboxPdfUrl,
   reading:p.pdfReading||{},
   onClose:()=>render(),
   onChange:reading=>{p.pdfReading=reading;state.updated=new Date().toISOString();persist()},
   onCounter:{
     get:()=>{const current=sec(p);return {section:current?.name||'No active section',count:current?.count||0,rows:current?.rows||0}},
     change:delta=>{const current=sec(p);if(!current)return;const previous=current.count;current.count=Math.max(0,Math.min(999999,current.count+delta));p.history??=[];p.history.push({at:new Date().toISOString(),section:current.id,from:previous,to:current.count});versionSnapshot(p);state.updated=new Date().toISOString();persist()}
   }
 })).catch(err=>alert('Pattern Reader could not open: '+err.message))
}else if(a==='importInstructions'){import('./pdf-import.js').then(m=>m.openPdfImporter(({name,columns})=>{const texts=columns.map(x=>x.replace(/\r\n/g,'\n'));while(texts.length>1&&!texts[texts.length-1].trim())texts.pop();const v={id:id(),name:'Imported: '+name,content:texts.join('\n\n'),columns:texts,original:false,completedLines:{},currentLine:''};versionSnapshot(p);p.versions.push(v);switchVersion(p,v.id);save()},{dropboxUrl:p.dropboxPdfUrl||''})).catch(e=>alert('PDF importer could not load: '+e.message))}else if(a==='organizeColumns'){const v=ver(p),cols=patternColumns(v);show('Arrange pattern columns',[{name:'column1',label:'Column 1 instructions',type:'textarea',value:cols[0]||''},{name:'column2',label:'Column 2 instructions (optional)',type:'textarea',value:cols[1]||''},{name:'column3',label:'Column 3 instructions (optional)',type:'textarea',value:cols[2]||''}],d=>{const items=[d.column1,d.column2,d.column3].map(x=>x.replace(/\r\n/g,'\n'));while(items.length>1&&!items[items.length-1].trim())items.pop();const next=v.original?{id:id(),name:'Working pattern',original:false}:v;next.columns=items;next.content=items.join('\n\n');next.completedLines={};next.currentLine='';if(v.original){versionSnapshot(p);p.versions.push(next);switchVersion(p,next.id)}},'<p class="help">Paste each printed column separately. Copying a whole PDF can mix up its column order. Rearranging resets line checkmarks for this working copy.</p>')}else if(a==='setDropboxLink'){show('Original Pattern PDF in Dropbox',[{name:'url',label:'Dropbox shared PDF link',type:'url',value:p.dropboxPdfUrl||'',required:true}],d=>{const u=new URL(d.url.trim());if(u.protocol!=='https:'||!(u.hostname==='dropbox.com'||u.hostname.endsWith('.dropbox.com')))throw Error('Enter an HTTPS Dropbox sharing link');p.dropboxPdfUrl=u.href})}else if(a==='importPattern'){const input=document.createElement('input');input.type='file';input.accept='.pdf,image/*';input.onchange=()=>{const file=input.files?.[0];if(!file)return;if(file.size>5*1024*1024){alert('This prototype limits pattern attachments to 5 MB.');return}const reader=new FileReader();reader.onload=()=>{p.attachment={name:file.name,data:reader.result};save()};reader.readAsDataURL(file)};input.click()}else if(a==='newYarn')show('Add yarn',[{name:'name',label:'Yarn name',required:true},{name:'weight',label:'Yarn weight'},{name:'unit',label:'Unit',value:'skeins'},{name:'total',label:'Total quantity',type:'number',min:0,value:1}],d=>state.yarn.push({id:id(),name:d.name,weight:d.weight,unit:d.unit,total:+d.total,reserved:0,used:0}));else if(a==='newTool')show('Add tool',[{name:'name',label:'Hook / needle / tool',required:true},{name:'size',label:'Size / type'}],d=>state.tools.push({id:id(),...d}));else if(a==='newGift')show('Plan a gift',giftFields(),d=>state.gifts.push({id:id(),...d}));else if(a==='newIdea')show('New idea',[{name:'title',label:'Idea',required:true},{name:'notes',label:'Notes',type:'textarea'}],d=>state.ideas.push({id:id(),...d}));else if(a==='dropboxSaveKey'){try{StudioDropbox.setKey(document.querySelector('#dropboxKey').value.trim());alert('Public app key saved.')}catch(e){alert(e.message)}}else if(a==='dropboxConnect'){StudioDropbox.connect().catch(e=>alert(e.message))}else if(a==='dropboxDisconnect'){StudioDropbox.disconnect();dropboxFeedback='Dropbox disconnected in this browser.';render()}else if(a==='dropboxTest'){dropboxFeedback='Checking Dropbox connection...';render();StudioDropbox.testConnection().then(()=>{dropboxFeedback='Dropbox responded successfully. Connection verified.';render()}).catch(e=>{dropboxFeedback='Connection test failed: '+e.message;render()})}else if(a==='dropboxSync'){syncDropbox().catch(e=>alert('Sync failed: '+e.message))}else if(a==='export'){exportBackup().catch(e=>alert('Export failed: '+e.message))}else if(a==='restore'){document.querySelector('#restoreInput')?.click()}}
function bind(){
 document.querySelectorAll('[data-gift-month]').forEach(b=>b.onclick=()=>{const d=new Date(giftYear,giftMonth+Number(b.dataset.giftMonth),1);giftYear=d.getFullYear();giftMonth=d.getMonth();selectedGiftDay=null;render()});
 document.querySelectorAll('[data-gift-day]').forEach(b=>b.onclick=()=>{selectedGiftDay=b.dataset.giftDay;render()});
 document.querySelectorAll('[data-edit-gift]').forEach(b=>b.onclick=()=>{const g=state.gifts.find(x=>x.id===b.dataset.editGift);if(g)show('Edit gift',giftFields(g),d=>Object.assign(g,d))});
 document.querySelectorAll('[data-delete-gift]').forEach(b=>b.onclick=()=>{const g=state.gifts.find(x=>x.id===b.dataset.deleteGift);if(g)ask('Remove this gift from Gift Planner?',()=>{state.gifts=state.gifts.filter(x=>x.id!==g.id)})});
 document.querySelectorAll('[data-pattern-check]').forEach(input=>input.onchange=()=>{const v=ver(active());v.completedLines??={};v.completedLines[input.dataset.patternCheck]=input.checked;save()});
 document.querySelectorAll('[data-pattern-select]').forEach(input=>input.onchange=()=>{const key=input.dataset.patternSelect;if(input.checked)patternDeleteSelection.add(key);else patternDeleteSelection.delete(key);const count=patternDeleteSelection.size;document.querySelectorAll('[data-pattern-bulk-delete]').forEach(b=>{b.disabled=count===0;b.textContent='Delete selected lines ('+count+')'});document.querySelectorAll('[data-pattern-clear-selection]').forEach(b=>b.disabled=count===0)});
 document.querySelectorAll('[data-pattern-clear-selection]').forEach(button=>button.onclick=()=>{patternDeleteSelection.clear();document.querySelectorAll('[data-pattern-select]').forEach(x=>x.checked=false);document.querySelectorAll('[data-pattern-bulk-delete]').forEach(b=>{b.disabled=true;b.textContent='Delete selected lines (0)'});document.querySelectorAll('[data-pattern-clear-selection]').forEach(b=>b.disabled=true)});
 document.querySelectorAll('[data-pattern-bulk-delete]').forEach(button=>button.onclick=()=>{const p=active(),v=ver(p);if(!v||v.original||!patternDeleteSelection.size)return;const count=patternDeleteSelection.size;if(!confirm('Delete '+count+' selected line(s) from this working pattern?\n\nThe original Dropbox PDF will not be changed.'))return;const removed=deleteWorkingPatternLines(v,patternDeleteSelection);patternDeleteSelection.clear();if(removed)save();else render()});
 document.querySelectorAll('[data-pattern-focus]').forEach(button=>button.onclick=()=>{const v=ver(active());v.currentLine=button.dataset.patternFocus;save()});
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{page=b.dataset.nav;mobileMoreOpen=false;query='';render()});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action));document.querySelector('#activeProject')?.addEventListener('change',e=>{state.active=e.target.value;save()});document.querySelector('#activeSection')?.addEventListener('change',e=>{active().activeSection=e.target.value;save()});document.querySelector('#activeVersion')?.addEventListener('change',e=>{switchVersion(active(),e.target.value);save()});document.querySelectorAll('[data-finishing-task]').forEach(el=>el.onchange=()=>{const t=(active().finishingTasks||[]).find(x=>x.id===el.dataset.finishingTask);if(t){t.done=el.checked;save()}});document.querySelector('#search')?.addEventListener('input',e=>{query=e.target.value;if(page!=='Home')render()});document.querySelectorAll('[data-choose]').forEach(b=>b.onclick=()=>{state.active=b.dataset.choose;page='Home';save()});document.querySelectorAll('[data-duplicate]').forEach(b=>b.onclick=()=>{const orig=state.projects.find(x=>x.id===b.dataset.duplicate),copy=structuredClone(orig);copy.id=id();copy.name+=' (copy)';copy.archived=false;copy.status='Planned';copy.sections=copy.sections.map(s=>({...s,id:id(),count:0,done:false}));copy.activeSection=copy.sections[0]?.id||'';copy.versions=copy.versions.map(v=>({...v,id:id()}));copy.activeVersion=copy.versions[0]?.id||'';copy.history=[];copy.finishingTasks=(copy.finishingTasks||[]).map(t=>({...t,id:id(),done:false}));copy.versionSectionStates={};versionSnapshot(copy);state.projects.push(copy);save()});document.querySelectorAll('[data-archive]').forEach(b=>b.onclick=()=>{const x=state.projects.find(p=>p.id===b.dataset.archive);x.archived=!x.archived;save()});document.querySelectorAll('[data-counter]').forEach(b=>b.onclick=()=>{const s=active().sections.find(s=>s.id===b.dataset.counter);s.count=Math.max(0,s.count+(+b.dataset.delta));save()});document.querySelectorAll('[data-editsection]').forEach(b=>b.onclick=()=>{active().activeSection=b.dataset.editsection;action('editSection')});document.querySelectorAll('[data-delete-note]').forEach(b=>b.onclick=()=>ask('Delete this note?',()=>{active().notes=active().notes.filter(n=>n.id!==b.dataset.deleteNote)}));document.querySelectorAll('[data-yarn]').forEach(b=>b.onclick=()=>{const y=state.yarn.find(x=>x.id===b.dataset.yarn);show('Adjust yarn quantities',[{name:'total',label:'Total owned',type:'number',min:0,value:y.total},{name:'reserved',label:'Reserved',type:'number',min:0,value:y.reserved},{name:'used',label:'Used',type:'number',min:0,value:y.used}],d=>{const t=+d.total,r=+d.reserved,u=+d.used;if([t,r,u].some(x=>x<0)||r+u>t){alert('Reserved plus used cannot exceed total.');return}Object.assign(y,{total:t,reserved:r,used:u})})});document.querySelector('#restoreInput')?.addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;try{const x=JSON.parse(await file.text());await validateBackup(x);ask('Replace ALL local records with this backup? Export your current data first.',()=>{state=prepareState(x.data);page='Home'})}catch(err){alert('Restore failed: '+err.message)}})}
async function digest(value){const bytes=new TextEncoder().encode(JSON.stringify(value));const hash=await crypto.subtle.digest('SHA-256',bytes);return [...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,'0')).join('')}
async function exportBackup(){versionSnapshot(active());await pendingWrites;const data=structuredClone(state);const backup={format:'sarah-studio-backup',version:2,exportedAt:new Date().toISOString(),checksumAlgorithm:'SHA-256',checksum:await digest(data),data};const blob=new Blob([JSON.stringify(backup,null,2)],{type:'application/json'});const u=URL.createObjectURL(blob),link=document.createElement('a');link.href=u;link.download='sarahs-studio-backup-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),10000)}
async function validateBackup(x){if(x.format!=='sarah-studio-backup'||![1,2].includes(x.version))throw Error('Unsupported backup format');prepareState(structuredClone(x.data));if(x.version===2){if(x.checksumAlgorithm!=='SHA-256'||!x.checksum)throw Error('Missing backup checksum');if(await digest(x.data)!==x.checksum)throw Error('Backup checksum mismatch: file may be damaged or modified');}}
async function syncDropbox(){
 versionSnapshot(active());await pendingWrites;
 const local={checksum:()=>digest(state),export:async()=>{const data=structuredClone(state);return {format:'sarah-studio-backup',version:2,exportedAt:new Date().toISOString(),checksumAlgorithm:'SHA-256',checksum:await digest(data),data}}};
 const result=await StudioDropbox.synchronize(local,validateBackup,async remote=>{
  if(!confirm('Replace all local records with Dropbox data? Export a backup before continuing.'))throw Error('Download cancelled');
  state=prepareState(structuredClone(remote));await StudioDB.put(state);page='Home';render();
 });alert('Dropbox sync: '+result);render();
}
async function initialize(){try{const returned=await StudioDropbox.callback();if(returned){page='Backup & Sync';dropboxFeedback=sessionStorage.getItem('studio-db-login-notice')||'Dropbox authorization completed.';sessionStorage.removeItem('studio-db-login-notice')}const existing=await StudioDB.get();if(existing){state=prepareState(existing)}else{const old=localStorage.getItem(KEY);state=old?prepareState(JSON.parse(old)):structuredClone(starter);await StudioDB.put(state);if(old)localStorage.removeItem(KEY)}persistenceReady=true;}catch(e){console.error(e);alert('Storage could not be initialized. Changes may not persist. '+e.message)}render()}
initialize();
